import type { Command } from '@type-pal/shared'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { legalPalette } from '../../__tests__/asset-fixtures.js'
import { dumpFramebuffer } from '../../__tests__/grok-render-r1/dump-evidence.js'
import type { GameState } from '../../core/game-state.js'
import { createInitialGameState } from '../../core/game-state.js'
import { setGlobalEvents } from '../../core/event-system.js'
import {
  confirmInventoryItem,
  createInventoryMenu,
  inventoryMoveRight,
  inventoryPageDown,
  MENUITEM_COLOR,
  MENUITEM_COLOR_EQUIPPEDITEM,
  MENUITEM_COLOR_INACTIVE,
  MENUITEM_COLOR_SELECTED_FIRST,
  MENUITEM_COLOR_SELECTED_INACTIVE,
} from '../../core/menu/inventory-menu.js'
import { fixtureGlyphs, textDot } from '../__tests__/glyph-fixtures.js'
import {
  freezeNow,
  makeGs,
  makeItem,
  makeLiveScene,
  makeRoles,
} from '../__tests__/menu-state-fixtures.js'
import { beginChineseMenuText, freezeMenuClock } from '../__tests__/menu-text-fixture.js'
import {
  BOX_STYLE0,
  BOX_STYLE1,
  CURSOR_HOLE,
  CURSOR_ID,
  cyanDigit,
  ITEMBOX_ID,
  makeUiFrames,
  rightDigitX,
  SLASH_ID,
  uiFramesWithoutSlot,
  yellowDigit,
} from '../__tests__/menu-ui-fixtures.js'
import {
  fillSentinel,
  iconImage,
  pixel,
  SENTINEL,
  sentinelFramebuffer,
} from '../__tests__/raster-fixtures.js'
import { cloneInputs } from '../__tests__/render-input-snapshots.js'
import { uniformDotGlyphs } from '../__tests__/uniform-glyphs.js'
import { createFramebuffer } from '../framebuffer.js'
import { flushToCanvas } from '../present.js'
import { drawInventoryMenu } from './draw-inventory.js'
const uniformGlyphs = uniformDotGlyphs()
const positionGlyphs = fixtureGlyphs()
const DESC = 0x3c
const DESC_COLOR = 0x3c
const EQUIPMENT_NAME_COLOR = 0xbe
const STAT_LABEL = 0xbb
const NAMES = '甲乙丙丁戊己庚辛壬癸子丑寅卯辰巳午未申酉戌亥'
function inventoryWithEntries(entries: { itemId: number; count: number }[]): GameState {
  const gs = createInitialGameState({ x: 0, y: 0, facing: 'down' })
  gs.inventory = entries
  return gs
}
function quantityDigitX(column: number, placeFromRight: number): number {
  return rightDigitX(15 + 81 + column * 100, 2, placeFromRight)
